"""Origin-aware TOML inputs and bounded script companion discovery."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from copy import deepcopy
from dataclasses import dataclass
import os
from pathlib import Path
import subprocess
import tomllib
from typing import TYPE_CHECKING, Literal, cast

import tomlkit

from .config_runtime import RuntimeConfig

if TYPE_CHECKING:
    from .layout import AgentLayout

PROJECTION_HEADER = (
    "# Generated by Toolang; edit the authored toolang.toml files instead.\n"
)
PROJECTION_KEY = "__toolang_sources__"


@dataclass(frozen=True, slots=True)
class ConfigSource:
    path: Path
    config: dict[str, object]
    scope: Literal["root", "home"] | None = None


def read_config(
    path: Path,
    *,
    include_workspaces: bool = True,
    origin: Path | None = None,
    runtime: RuntimeConfig | None = None,
) -> dict[str, object]:
    """Read one optional TOML file, preserving its discovered path as origin."""
    if not path.exists() and not path.is_symlink():
        return {}
    try:
        return rebase_config(
            tomllib.loads(path.read_text(encoding="utf-8")),
            (origin or path).parent,
            include_workspaces=include_workspaces,
            runtime=runtime,
        )
    except (OSError, ValueError) as exc:
        raise ValueError(f"could not read configuration {path}: {exc}") from exc


def rebase_config(
    config: Mapping[str, object],
    directory: Path,
    *,
    include_workspaces: bool = True,
    runtime: RuntimeConfig | None = None,
) -> dict[str, object]:
    """Resolve known host paths; plugin commands and guest paths remain opaque."""
    result = deepcopy(dict(config))
    if not include_workspaces:
        result.pop("workspaces", None)
    workspaces = result.get("workspaces")
    if isinstance(workspaces, dict):
        workspaces = cast(dict[str, object], workspaces)
        for name, path in workspaces.items():
            if isinstance(path, str) and path:
                workspaces[name] = str(resolve_path(path, directory, runtime=runtime))
    catalog = catalog_config(result)
    if catalog is not None and isinstance(catalog.get("path"), str) and catalog["path"]:
        catalog["path"] = str(
            resolve_path(str(catalog["path"]), directory, runtime=runtime)
        )
    return result


def rebase_config_content(
    content: bytes,
    directory: Path,
    *,
    include_workspaces: bool = True,
    runtime: RuntimeConfig | None = None,
) -> bytes:
    """Bind relative paths into captured bytes without changing unrelated files."""
    parsed = tomllib.loads(content.decode("utf-8"))
    resolved = rebase_config(
        parsed, directory, include_workspaces=include_workspaces, runtime=runtime
    )
    return content if parsed == resolved else tomlkit.dumps(resolved).encode("utf-8")


def resolve_path(
    value: str, directory: Path, *, runtime: RuntimeConfig | None = None
) -> Path:
    if runtime is not None:
        return runtime.resolve_path(value, directory)
    path = Path(value).expanduser()
    return (path if path.is_absolute() else directory / path).resolve()


def catalog_config(config: Mapping[str, object]) -> dict[str, object] | None:
    value: object = config
    for key in ("plugin", "model_catalog", "models_dev"):
        value = value.get(key) if isinstance(value, dict) else None
    return cast(dict[str, object], value) if isinstance(value, dict) else None


def script_directories(source: Path) -> tuple[Path, ...]:
    """Return source-first directories through the nearest Git worktree boundary."""
    srcdir = source.resolve(strict=True).parent
    for directory in (srcdir, *srcdir.parents):
        marker = directory / ".git"
        if not marker.exists() and not marker.is_symlink():
            continue
        environ = {
            key: value
            for key, value in os.environ.items()
            if not key.startswith("GIT_")
        }
        result = subprocess.run(
            ["git", "-C", str(directory), "rev-parse", "--show-toplevel"],
            env=environ,
            capture_output=True,
            text=True,
            check=False,
        )
        if result.returncode or Path(result.stdout.strip()).resolve() != directory:
            raise ValueError(f"invalid Git worktree boundary: {marker}")
        return tuple(
            parent
            for parent in (srcdir, *srcdir.parents)
            if parent == directory or parent.is_relative_to(directory)
        )
    return (srcdir,)


def script_sources(source: Path) -> tuple[ConfigSource, ...]:
    """Capture outer-to-inner layers without inheriting ancestor workspace grants."""
    directories = script_directories(source)
    sources: list[ConfigSource] = []
    for directory in reversed(directories):
        path = directory / "toolang.toml"
        companion = directory / "toolang.catalog.json"
        if not any(item.exists() or item.is_symlink() for item in (path, companion)):
            continue
        config = read_config(path, include_workspaces=directory == directories[0])
        _reject_local_environment(config, path)
        # Catalog-only layers retain their position without requiring TOML.
        sources.append(ConfigSource(path, config))
    return tuple(sources)


def config_sources(
    layout: AgentLayout, *, include_agent: bool = True
) -> tuple[ConfigSource, ...]:
    """Load normal root/home layers or captured roaming project layers."""
    runtime = layout.runtime_config or RuntimeConfig()
    if layout.project_inputs:
        config = read_config(
            layout.place_config,
            include_workspaces=False,
            origin=runtime.origin("root", layout.place_config),
            runtime=layout.runtime_config,
        )
        _reject_local_environment(config, layout.place_config)
        raw = config.get(PROJECTION_KEY)
        if isinstance(raw, list):
            sources = tuple(
                ConfigSource(
                    Path(str(item["path"])),
                    cast(dict[str, object], item["config"]),
                    "root",
                )
                for item in cast(list[dict[str, object]], raw)
            )
            for source in sources:
                _reject_local_environment(source.config, source.path)
        else:
            sources = (
                ConfigSource(
                    runtime.origin("root", layout.place_config), config, "root"
                ),
            )
        defaults = runtime.defaults.get("root", {})
        overlay = runtime.overlays.get("root", {})
        root = runtime.origin("root", layout.place_config)
        sources = (
            *((ConfigSource(root, deepcopy(defaults), "root"),) if defaults else ()),
            *sources,
            *(
                (
                    ConfigSource(
                        root,
                        {
                            key: deepcopy(value)
                            for key, value in overlay.items()
                            if key != "workspaces"
                        },
                        "root",
                    ),
                )
                if overlay
                else ()
            ),
        )
        if include_agent:
            home = runtime.apply(
                "home",
                read_config(
                    layout.config,
                    origin=runtime.origin("home", layout.config),
                    runtime=layout.runtime_config,
                ),
            )
            _reject_local_environment(home, layout.config)
            if (
                home
                or layout.config.exists()
                or layout.config.is_symlink()
                or (layout.home / "catalog.json").exists()
                or (layout.home / "catalog.json").is_symlink()
            ):
                sources += (
                    ConfigSource(runtime.origin("home", layout.config), home, "home"),
                )
        return sources
    paths = (
        ("root", layout.place_config),
        *(((("home", layout.config),)) if include_agent else ()),
    )
    sources = tuple(
        ConfigSource(
            runtime.origin(scope, path),
            runtime.apply(
                scope,
                read_config(
                    path,
                    include_workspaces=scope == "home",
                    origin=runtime.origin(scope, path),
                    runtime=layout.runtime_config,
                ),
            ),
            scope,
        )
        for scope, path in paths
    )
    for source in sources:
        if source.scope != "root" or layout.placement != "resident":
            _reject_local_environment(source.config, source.path)
    return sources


def _reject_local_environment(config: Mapping[str, object], path: Path) -> None:
    if "env" in config:
        raise ValueError(f"{path}: env is supported only in the Toolang root config")


def merge_mappings(layers: Sequence[Mapping[str, object]]) -> dict[str, object]:
    """Merge mapping fields for inspection and State, not Setup policy resolution."""
    result: dict[str, object] = {}
    for layer in layers:
        for key, value in layer.items():
            previous = result.get(key)
            result[key] = (
                merge_mappings(
                    (cast(dict[str, object], previous), cast(dict[str, object], value))
                )
                if isinstance(previous, dict) and isinstance(value, dict)
                else deepcopy(value)
            )
    return result


def project_sources(
    sources: Sequence[ConfigSource], *, source: Path, catalog: Path | None = None
) -> str:
    """Keep the original ordered layers alongside the State-facing projection."""
    config = merge_mappings([item.config for item in sources])
    config[PROJECTION_KEY] = [
        {"path": str(item.path), "config": item.config} for item in sources
    ]
    config["__toolang_source__"] = str(source)
    if catalog is not None:
        config["__toolang_catalog__"] = str(catalog)
    return PROJECTION_HEADER + tomlkit.dumps(config)


def source_catalog(
    sources: Sequence[ConfigSource], *, roaming: bool, validate: bool = True
) -> Path | None:
    """Pick the nearest authored path or companion without merging catalogs."""
    for source in reversed(sources):
        config = catalog_config(source.config)
        if config is not None and "path" in config:
            path = config["path"]
            if not isinstance(path, str) or not path:
                raise ValueError(f"model catalog path must be nonempty: {source.path}")
            selected = Path(path)
        else:
            selected = source.path.with_name(
                "toolang.catalog.json"
                if roaming and source.scope != "home"
                else "catalog.json"
            )
            if not selected.exists() and not selected.is_symlink():
                continue
        if validate and not selected.is_file():
            raise ValueError(f"model catalog is not a file: {selected}")
        return selected
    return None
